{"task_id": "T35", "code": "def solve(grid):
    """Count the number of islands (connected components of 1s) in a grid.
    The grid may be empty or jagged. Cells are connected 4-directionally.
    """
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            visited.add((i, j))
            # four directions
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < rows and 0 <= nj < len(grid[ni]) and (ni, nj) not in visited and grid[ni][nj] == 1:
                    stack.append((ni, nj))
    count = 0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j] == 1 and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count"}

